export type UdfRoute = 'config' | 'search' | 'symbols' | 'history';
export type UdfQuery<Route extends UdfRoute> = Route extends 'config'
    ? Record<string, never>
    : Route extends 'search'
      ? {
            readonly query?: string;
            readonly type?: string;
            readonly exchange?: string;
            readonly limit?: number;
        }
      : Route extends 'symbols'
        ? { readonly symbol: string }
        : {
              readonly symbol: string;
              readonly resolution: Resolution;
              readonly from?: number;
              readonly to?: number;
              readonly countback?: number;
          };
export type UdfResponse<Route extends UdfRoute> = Route extends 'config'
    ? UdfConfigResponse
    : Route extends 'search'
      ? UdfSearchResponse
      : Route extends 'symbols'
        ? UdfSymbolResponse
        : UdfHistoryResponse;
